const b = typeof $json.body === 'string' ? JSON.parse($json.body) : ($json.body || {});
const prices = (b.prices || []).map(p => p[1]).filter(x => typeof x === 'number');
const rets = prices.slice(1).map((p, i) => (p - prices[i]) / prices[i]);
const mean = rets.length ? rets.reduce((a, b) => a + b, 0) / rets.length : 0;
const vol = rets.length ? Math.sqrt(rets.reduce((a, b) => a + (b - mean) ** 2, 0) / rets.length) * 100 : 0;
const trend = prices.length > 1 ? (prices[prices.length - 1] - prices[0]) / prices[0] * 100 : 0;
const hi = prices.length ? Math.max(...prices) : 0;
const lo = prices.length ? Math.min(...prices) : 0;
const range = hi ? (hi - lo) / hi * 100 : 0;
[{ json: { volatility_7d_pct: Math.round(vol * 100) / 100, trend_7d_pct: Math.round(trend * 100) / 100, range_7d_pct: Math.round(range * 100) / 100, points: prices.length } }];

